landmark.sql:
CREATE TABLE ai_permanent_holdouts (image_id TEXT PRIMARY KEY,reserved_at TEXT NOT NULL,FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE TABLE annotation_drafts (image_id TEXT PRIMARY KEY,workflow_stage TEXT,workflow_position INTEGER,manual_rebuild INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE TABLE corrections (correction_id INTEGER PRIMARY KEY,image_id TEXT NOT NULL,landmark_id INTEGER,kind TEXT NOT NULL,previous_json TEXT,accepted_json TEXT,created_at TEXT NOT NULL, landmark_abbr TEXT,FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE TABLE crop_evaluations (evaluation_id TEXT PRIMARY KEY,holdout_id TEXT NOT NULL,model_id TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE crop_holdout (holdout_id TEXT NOT NULL,image_id TEXT NOT NULL,seed INTEGER NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(holdout_id,image_id),FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE TABLE crop_holdout_references (reference_id TEXT PRIMARY KEY,holdout_id TEXT NOT NULL,image_id TEXT NOT NULL,crop_json TEXT NOT NULL,revision INTEGER NOT NULL,created_at TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE TABLE crop_predictions (prediction_id TEXT PRIMARY KEY,image_id TEXT NOT NULL,model_id TEXT,proposal_json TEXT NOT NULL,qc_level TEXT,qc_score INTEGER,qc_reasons_json TEXT,created_at TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE TABLE crop_training_membership (model_id TEXT NOT NULL,image_id TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(model_id,image_id),FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE TABLE crop_verified_observations (image_id TEXT PRIMARY KEY,verified_at TEXT NOT NULL,FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE TABLE crops (image_id TEXT PRIMARY KEY,developed_relpath TEXT,standardized_relpath TEXT,source_sha256 TEXT,crop_json TEXT,transform_json TEXT,rotation_degrees REAL,status TEXT,provenance TEXT,model_id TEXT,updated_at TEXT NOT NULL, active_prediction_id TEXT, ai_proposal_json TEXT, human_verified INTEGER NOT NULL DEFAULT 0, human_changed INTEGER NOT NULL DEFAULT 0, prediction_at TEXT, reviewed_at TEXT, qc_level TEXT, qc_score INTEGER, qc_reasons_json TEXT,FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE TABLE image_attributes (image_id TEXT NOT NULL,attribute_key TEXT NOT NULL,value TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(image_id,attribute_key),FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE TABLE image_review (image_id TEXT PRIMARY KEY,human_verified INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE TABLE images (image_id TEXT PRIMARY KEY,original_name TEXT NOT NULL,relative_path TEXT NOT NULL,sample_id TEXT,file_size INTEGER,mtime_ns INTEGER,width INTEGER,height INTEGER,source_sha256 TEXT,source_available INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, locality TEXT, index_in_locality INTEGER, total_in_locality INTEGER, specimen_id TEXT, excluded INTEGER NOT NULL DEFAULT 0, exclusion_reason TEXT, exclusion_note TEXT);
CREATE TABLE landmark_schema (landmark_id INTEGER PRIMARY KEY,abbr TEXT NOT NULL UNIQUE,name TEXT NOT NULL);
CREATE TABLE landmarks (image_id TEXT NOT NULL,landmark_id INTEGER NOT NULL,x_standardized REAL,y_standardized REAL,x_original REAL,y_original REAL,state TEXT NOT NULL,provenance TEXT NOT NULL,model_id TEXT,predicted_x REAL,predicted_y REAL,confidence REAL,prediction_run_id TEXT,reviewed INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL, landmark_abbr TEXT,PRIMARY KEY(image_id,landmark_id),FOREIGN KEY(image_id) REFERENCES images(image_id),FOREIGN KEY(landmark_id) REFERENCES landmark_schema(landmark_id));
CREATE TABLE locality_calibrations (locality_id TEXT PRIMARY KEY,scale REAL NOT NULL,units TEXT NOT NULL,calibration_reference_image_id TEXT NOT NULL,calibration_data TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE models (model_id TEXT PRIMARY KEY,kind TEXT NOT NULL,schema_sha256 TEXT,path TEXT,active INTEGER NOT NULL DEFAULT 0,pinned INTEGER NOT NULL DEFAULT 0,metrics_json TEXT,dataset_id TEXT,parent_model_id TEXT,dataset_manifest_path TEXT,created_at TEXT NOT NULL);
CREATE TABLE project (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE qc (qc_id INTEGER PRIMARY KEY,image_id TEXT,kind TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE TABLE training_examples (example_id INTEGER PRIMARY KEY,image_id TEXT NOT NULL,kind TEXT NOT NULL,label_json TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,FOREIGN KEY(image_id) REFERENCES images(image_id));
CREATE INDEX idx_landmarks_image_abbr ON landmarks(image_id,landmark_abbr);

xray.sql:
CREATE TABLE annotation_archives(
          archive_id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL,
          specimen_id TEXT NOT NULL, created_at TEXT NOT NULL, reason TEXT NOT NULL,
          crop_json TEXT NOT NULL DEFAULT '{}', annotations_json TEXT NOT NULL DEFAULT '[]',
          structure_states_json TEXT NOT NULL DEFAULT '{}',
          schema_version_id TEXT NOT NULL, pass_no INTEGER NOT NULL, source TEXT NOT NULL,
          status TEXT NOT NULL DEFAULT ''
        );
CREATE TABLE annotation_events(
          event_id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL,
          created_at TEXT NOT NULL, action TEXT NOT NULL, structure_id TEXT NOT NULL DEFAULT '',
          annotation_id INTEGER, payload_json TEXT NOT NULL DEFAULT '{}',
          FOREIGN KEY(run_id) REFERENCES annotation_runs(run_id)
        );
CREATE TABLE annotation_roles(
          role_id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL,
          annotation_id INTEGER NOT NULL, structure_id TEXT NOT NULL,
          created_at TEXT NOT NULL,
          UNIQUE(run_id,structure_id),
          FOREIGN KEY(run_id) REFERENCES annotation_runs(run_id) ON DELETE CASCADE,
          FOREIGN KEY(annotation_id) REFERENCES annotations(annotation_id) ON DELETE CASCADE
        );
CREATE TABLE annotation_runs(
          run_id TEXT PRIMARY KEY, specimen_id TEXT NOT NULL, pass_no INTEGER NOT NULL,
          source TEXT NOT NULL, schema_version_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft',
          coordinate_space TEXT NOT NULL DEFAULT 'crop_normalized_v1',
          created_at TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT '', verified_at TEXT NOT NULL DEFAULT '',
          UNIQUE(specimen_id,pass_no,source,schema_version_id)
        );
CREATE TABLE annotation_structure_states(
          run_id TEXT NOT NULL, structure_id TEXT NOT NULL,
          visibility TEXT NOT NULL DEFAULT 'complete', updated_at TEXT NOT NULL DEFAULT '',
          PRIMARY KEY(run_id,structure_id),
          FOREIGN KEY(run_id) REFERENCES annotation_runs(run_id) ON DELETE CASCADE
        );
CREATE TABLE annotations(
          annotation_id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL,
          structure_id TEXT NOT NULL, x REAL NOT NULL, y REAL NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0,
          FOREIGN KEY(run_id) REFERENCES annotation_runs(run_id) ON DELETE CASCADE
        );
CREATE TABLE crop_events(
          event_id INTEGER PRIMARY KEY AUTOINCREMENT, specimen_id TEXT NOT NULL,
          created_at TEXT NOT NULL, action TEXT NOT NULL, source TEXT NOT NULL,
          payload_json TEXT NOT NULL DEFAULT '{}',
          FOREIGN KEY(specimen_id) REFERENCES specimens(specimen_id)
        );
CREATE TABLE meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE schema_versions(
          version_id TEXT PRIMARY KEY, created_at TEXT NOT NULL, scheme_hash TEXT NOT NULL,
          note TEXT NOT NULL DEFAULT '', payload_json TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 0
        );
CREATE TABLE source_images(
          image_id TEXT PRIMARY KEY, relative_path TEXT NOT NULL UNIQUE, excluded INTEGER NOT NULL DEFAULT 0,
          crop_reviewed INTEGER NOT NULL DEFAULT 0, crop_reviewed_at TEXT NOT NULL DEFAULT ''
        );
CREATE TABLE specimens(
          specimen_id TEXT PRIMARY KEY, image_id TEXT NOT NULL, label TEXT NOT NULL,
          crop_json TEXT, excluded INTEGER NOT NULL DEFAULT 0, ordinal INTEGER NOT NULL DEFAULT 0,
          crop_source TEXT NOT NULL DEFAULT '', crop_status TEXT NOT NULL DEFAULT 'proposed',
          crop_qc_json TEXT NOT NULL DEFAULT '[]', model_id TEXT NOT NULL DEFAULT '',
          updated_at TEXT NOT NULL DEFAULT '',
          FOREIGN KEY(image_id) REFERENCES source_images(image_id)
        );
CREATE TABLE trait_results(
          specimen_id TEXT NOT NULL, trait_id TEXT NOT NULL, schema_version_id TEXT NOT NULL,
          value_text TEXT, qc_note TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL,
          PRIMARY KEY(specimen_id,trait_id,schema_version_id)
        );
CREATE TABLE ui_state(
          key TEXT PRIMARY KEY, payload_json TEXT NOT NULL DEFAULT '{}'
        );
CREATE TABLE xray_crop_models(
          model_id TEXT PRIMARY KEY, created_at TEXT NOT NULL, path TEXT NOT NULL,
          config_path TEXT NOT NULL DEFAULT '', parent_model_id TEXT,
          metrics_json TEXT NOT NULL DEFAULT '{}', training_plate_count INTEGER NOT NULL DEFAULT 0,
          training_specimen_count INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 0
        );
CREATE TABLE xray_crop_training_membership(
          model_id TEXT NOT NULL, image_id TEXT NOT NULL,
          PRIMARY KEY(model_id,image_id),
          FOREIGN KEY(model_id) REFERENCES xray_crop_models(model_id),
          FOREIGN KEY(image_id) REFERENCES source_images(image_id)
        );
CREATE TABLE xray_structure_models(
          model_id TEXT PRIMARY KEY, created_at TEXT NOT NULL, path TEXT NOT NULL,
          metadata_path TEXT NOT NULL, parent_model_id TEXT, schema_digest TEXT NOT NULL,
          backend TEXT NOT NULL, metrics_json TEXT NOT NULL DEFAULT '{}',
          training_specimen_count INTEGER NOT NULL DEFAULT 0,
          validation_specimen_count INTEGER NOT NULL DEFAULT 0,
          active INTEGER NOT NULL DEFAULT 0
        );
CREATE TABLE xray_structure_repeatability_membership(
          run_id TEXT NOT NULL, specimen_id TEXT NOT NULL, position INTEGER NOT NULL,
          baseline_json TEXT NOT NULL DEFAULT '[]',
          baseline_visibility_json TEXT NOT NULL DEFAULT '{}',
          PRIMARY KEY(run_id,specimen_id),
          FOREIGN KEY(run_id) REFERENCES xray_structure_repeatability_runs(run_id) ON DELETE CASCADE,
          FOREIGN KEY(specimen_id) REFERENCES specimens(specimen_id)
        );
CREATE TABLE xray_structure_repeatability_runs(
          run_id TEXT PRIMARY KEY, schema_version_id TEXT NOT NULL,
          created_at TEXT NOT NULL, completed_at TEXT NOT NULL DEFAULT '',
          status TEXT NOT NULL DEFAULT 'in_progress',
          requested_count INTEGER NOT NULL DEFAULT 0, seed INTEGER NOT NULL DEFAULT 42,
          annotation1_pass_no INTEGER NOT NULL DEFAULT 0,
          annotation2_pass_no INTEGER NOT NULL DEFAULT 0
        );
CREATE TABLE xray_structure_training_membership(
          model_id TEXT NOT NULL, specimen_id TEXT NOT NULL, split TEXT NOT NULL,
          PRIMARY KEY(model_id,specimen_id),
          FOREIGN KEY(model_id) REFERENCES xray_structure_models(model_id),
          FOREIGN KEY(specimen_id) REFERENCES specimens(specimen_id)
        );
